  // ----- 7/8a) Beyan ONAY otomasyonu (2.7.139): MUBiS beyan listesinde
  // "onaylandi" isaretlenen musteri/donem/tur icin e-Beyanname (vergi) veya
  // SGK e-Bildirge (sigorta) sisteminden beyanname + tahakkuk (+ hizmet
  // belgesi) belgelerini indirir ve G:\Drive'ım\BEYANNAME arsivine kopyalar.
  "eb-beyan-otomatik-indir": async (p) => ebBeyanOtomatikIndir(p),
  // ----- 8d) Windows WhatsApp uygulamasindan gonderim (2.7.172):
  // whatsapp:// derin baglantisiyla MASASTU WhatsApp programi acilir (mesaj
  // hazir), uygulama odaklanir ve Enter gonderilir. Uygulama kurulu degilse /
  // odaklanamazsa aciklayan yanit doner; web taraf tarayiciya duser.
  "whatsapp-desktop-gonder": async (p) => {
    let telefon = String(p.telefon || p.phone || "").replace(/\D/g, "");
    const mesaj = String(p.mesaj || p.message || "");
    if (!telefon) throw new Error("Telefon numarasi belirtilmedi.");
    if (telefon.startsWith("0")) telefon = telefon.slice(1);
    if (!telefon.startsWith("90")) telefon = "90" + telefon;
    if (!mesaj) throw new Error("Mesaj bos olamaz.");
    const uri = "whatsapp://send?phone=" + telefon + "&text=" + encodeURIComponent(mesaj);
    console.log("[whatsapp-desktop-gonder] basladi, hedef:", telefon);
    const ps = `$ErrorActionPreference='SilentlyContinue'; Start-Process '${uri}'; Start-Sleep -Seconds 9; try { Add-Type -AssemblyName Microsoft.VisualBasic; Add-Type -AssemblyName System.Windows.Forms; $w = Get-Process | Where-Object { $_.ProcessName -like '*WhatsApp*' -and $_.MainWindowHandle -ne 0 } | Select-Object -First 1; if ($w) { [Microsoft.VisualBasic.Interaction]::AppActivate($w.Id); Start-Sleep -Milliseconds 900; [System.Windows.Forms.SendKeys]::SendWait('~'); Write-Output 'SENT' } else { Write-Output 'NO_APP' } } catch { Write-Output 'FOCUS_FAIL' }`;
    const cikti = await new Promise((resolve) => {
      exec(`powershell -NoProfile -ExecutionPolicy Bypass -Command "${ps}"`, { windowsHide: true, timeout: 45e3 }, (e, so) => resolve(String(so || "").trim() || (e ? "HATA:" + e.message : "")));
    });
    console.log("[whatsapp-desktop-gonder] sonuc:", cikti);
    if (cikti === "SENT") return { ok: true, gonderildi: true, telefon, not: "Windows WhatsApp uygulamasindan gonderildi." };
    if (cikti === "NO_APP") return {
      ok: false,
      reason: "uygulama-yok",
      not: "Windows WhatsApp uygulamasina ulasilamadi (kurulu degil veya acilmadi)."
    };
    return {
      ok: false,
      reason: "odak-hatasi",
      not: "WhatsApp penceresi acildi ancak otomatik gonderilemedi \u2014 acilan sohbette ENTER'a basin."
    };
  },
  // ----- 8c) SMTP mail gonderimi (2.7.171): Cloudflare Workers raw SMTP
  // acamadigi icin e-posta LOKAL yardimci programdan gider (nodemailer).
  // Parametreler: host, port, secure, user, pass, from, to, toName, subject,
  // mesaj, documents: [{url, name}] (URL'ler indirilip eklenir).
  "mail-gonder": async (p) => {
    const nodemailer = require('nodemailer');
    if (!p.host || !p.user || !p.pass) throw new Error("SMTP ayarlari eksik");
    if (!p.to) throw new Error("Alici e-posta adresi yok");
    const transporter = nodemailer.createTransport({
      host: p.host,
      port: parseInt(p.port, 10) || 465,
      secure: p.secure !== false,
      auth: { user: p.user, pass: p.pass }
    });
    const attachments = [];
    for (const d of p.documents || []) {
      try {
        const r = await fetch(d.url);
        if (!r.ok) continue;
        const buf = Buffer.from(await r.arrayBuffer());
        attachments.push({ filename: d.name || "belge.pdf", content: buf });
      } catch (e) {
        console.log("[mail-gonder] ek indirilemedi:", d.name, e.message);
      }
    }
    await transporter.sendMail({
      from: p.from || p.user,
      to: p.to,
      subject: p.subject || "MUBiS bildirimi",
      text: p.mesaj || "",
      html: p.html || void 0,
      attachments
    });
    console.log("[mail-gonder]", p.to, "| ek:", attachments.length);
    return { ok: true, to: p.to, ekAdet: attachments.length };
  },
  // ----- 8b) Beyan arsivi kontrolu (2.7.170): G:\...\BEYANNAME\<musteri>\<tur>
  // \<yil>\<ay> klasorunu LISTELER (klasor acmaz, tarayici acmaz). Web "onaylandi"
  // secilince once buraya bakar; klasorde beyanname/tahakkuk varsa GIB'e
  // baglanmadan belgeler MUBiS'e yuklenip musterive gonderilir.
  "eb-arsiv-listele": async (p) => {
    const hedef = beyanHedefKlasor(p);
    if (!hedef) throw new Error("Arsiv klasoru hesaplanamadi (beyanKok ayari bos)");
    let dosyalar = [];
    try {
      dosyalar = fs.readdirSync(hedef).filter((f) => /\.(pdf|xlsx|xls|xml)$/i.test(f)).map((f) => {
        const tam = path.join(hedef, f);
        const st = fs.statSync(tam);
        return { ad: f, yol: tam, boyut: st.size, tarih: st.mtimeMs };
      }).sort((a, b) => b.tarih - a.tarih);
    } catch {
    }
    console.log("[eb-arsiv-listele]", hedef, "->", dosyalar.length, "dosya");
    return { ok: true, hedef, adet: dosyalar.length, dosyalar };
  },
