function eimzaAraciDinliyorMu() {
  return new Promise((resolve) => {
    try {
      const istek = https.get(
        { host: "localhost", port: EIMZA_PORT, path: "/", rejectUnauthorized: false, timeout: 2500 },
        (r) => {
          r.resume();
          resolve(true);
        }
      );
      istek.on("error", () => resolve(false));
      istek.on("timeout", () => {
        istek.destroy();
        resolve(false);
      });
    } catch (e) {
      resolve(false);
    }
  });
}
function javawsBul() {
  try {
    const out = execSync("where javaws 2>nul", { encoding: "utf8" });
    const ilk = String(out || "").split(/\r?\n/).find((x) => x.trim().toLowerCase().endsWith("javaws.exe"));
    if (ilk) return { exe: ilk.trim(), tip: "javaws" };
  } catch (e) {
  }
  const kokler = ["C:\\Program Files\\Java", "C:\\Program Files (x86)\\Java", "C:\\Program Files\\Eclipse Adoptium", "C:\\Program Files\\Eclipse Foundation", "C:\\Program Files\\Microsoft"];
  for (const kok of kokler) {
    try {
      if (!fs.existsSync(kok)) continue;
      for (const alt of fs.readdirSync(kok)) {
        const javaws = path.join(kok, alt, "bin", "javaws.exe");
        if (fs.existsSync(javaws)) return { exe: javaws, tip: "javaws" };
        const jp2 = path.join(kok, alt, "bin", "jp2launcher.exe");
        if (fs.existsSync(jp2)) return { exe: jp2, tip: "jp2launcher" };
      }
    } catch (e) {
    }
  }
  const javapath = "C:\\Program Files (x86)\\Common Files\\Oracle\\Java\\javapath\\javaws.exe";
  if (fs.existsSync(javapath)) return { exe: javapath, tip: "javaws" };
  try {
    const out2 = execSync("where jp2launcher 2>nul", { encoding: "utf8" });
    const ilk2 = String(out2 || "").split(/\r?\n/).find((x) => x.trim().toLowerCase().endsWith("jp2launcher.exe"));
    if (ilk2) return { exe: ilk2.trim(), tip: "jp2launcher" };
  } catch (e) {
  }
  return null;
}
function jnlpYoluBul() {
  const adaylar = [
    path.join(os.homedir(), "Desktop", "EFaturaWebSocket.jnlp"),
    path.join(os.homedir(), "Masa\xFCst\xFC", "EFaturaWebSocket.jnlp"),
    path.join(os.homedir(), "Downloads", "EFaturaWebSocket.jnlp"),
    path.join(os.homedir(), "\u0130ndirilenler", "EFaturaWebSocket.jnlp")
  ];
  for (const a of adaylar) {
    if (fs.existsSync(a)) return a;
  }
  const hedef = path.join(os.tmpdir(), "EFaturaWebSocket.jnlp");
  try {
    execSync(`powershell -NoProfile -Command "[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12; (New-Object Net.WebClient).DownloadFile('https://ebelge.gib.gov.tr/EFaturaWebSocket/EFaturaWebSocket.jnlp', '` + hedef.replace(/'/g, "''") + `')"`, { timeout: 3e4, windowsHide: true });
    if (fs.existsSync(hedef)) return hedef;
  } catch (e) {
  }
  return null;
}
async function eimzaAraciniBaslat(log) {
  if (await eimzaAraciDinliyorMu()) {
    log("imzalama araci zaten calisiyor (localhost:8543)");
    return true;
  }
  const jnlp = jnlpYoluBul();
  if (!jnlp) throw new Error("EFaturaWebSocket.jnlp bulunamadi (Masaustu/Indirilenler arandi, GIB indirmesi de basarisiz). Dosyayi Masaustune koyup tekrar deneyin.");
  const javaws = javawsBul();
  if (!javaws) throw new Error("Java (javaws.exe / jp2launcher.exe) bulunamadi. Imzalama araci icin Java kurulu olmali; kurduktan sonra tekrar deneyin.");
  log("imzalama araci baslatiliyor:", javaws.tip, javaws.exe, jnlp);
  try {
    const cocuk = spawn(javaws.exe, [jnlp], { detached: true, stdio: "ignore" });
    cocuk.unref();
  } catch (e) {
    throw new Error("Imzalama araci baslatilamadi: " + (e && e.message || e));
  }
  for (let i = 0; i < 60; i++) {
    await _eimzaBekle(2e3);
    if (await eimzaAraciDinliyorMu()) {
      log("imzalama araci hazir (localhost:8543)");
      log("imzalama araci tam baslangici icin 6 saniye ek bekleniyor...");
      await _eimzaBekle(6e3);
      return true;
    }
  }
  throw new Error("Imzalama araci 120 saniyede localhost:8543 dinlemeye baslamadi. Java guvenlik uyarisi cikmissa onaylayin; jnlp elle calistirilabilir.");
}
async function eimzaAraciniKapat(log) {
  log = log || (() => {
  });
  try {
    const jnlp = jnlpYoluBul();
    if (jnlp) {
      try {
        const cmd = `powershell -NoProfile -Command "Get-CimInstance Win32_Process -Filter \\"CommandLine LIKE '%${path.basename(jnlp)}%'\\" | Remove-CimInstance -Confirm:$false"`;
        execSync(cmd, { encoding: "utf8", timeout: 15e3 });
        log("imzalama araci javaws surecleri kapatildi (cim)");
      } catch (e) {
        log("imzalama araci cim kapatma:", String(e).slice(0, 160));
      }
    }
    try {
      execSync("taskkill /F /IM javaws.exe 2>nul", { encoding: "utf8", timeout: 1e4 });
      log("imzalama araci javaws.exe kapatildi (taskkill)");
    } catch (e) {
      log("imzalama araci taskkill:", String(e).slice(0, 120));
    }
    try {
      execSync("taskkill /F /IM jp2launcher.exe 2>nul", { encoding: "utf8", timeout: 1e4 });
      log("imzalama araci jp2launcher.exe kapatildi (taskkill)");
    } catch (e) {
      log("imzalama araci jp2launcher taskkill:", String(e).slice(0, 120));
    }
    await _eimzaBekle(2500);
    if (await eimzaAraciDinliyorMu()) log("imzalama araci hala dinliyor (elle kapatilmasi gerekebilir)");
    else log("imzalama araci kapandi");
  } catch (e) {
    log("eimzaAraciniKapat hata:", String(e).slice(0, 120));
  }
}
