      const serbest = adaylar.filter((x) => !adaylar.some((y) => y !== x && x.contains(y)));
      const icteki = serbest.sort((a, b) => norm(a.textContent || a.value || "").length - norm(b.textContent || b.value || "").length)[0];
      if (!icteki) return null;
